```zig
const std = @import("std");
const mem = std.mem;

pub const Triplet = struct {
    a: usize,
    b: usize,
    c: usize,

    pub fn init(a: usize, b: usize, c: usize) Triplet {
        return Triplet{ .a = a, .b = b, .c = c };
    }
};

pub fn tripletsWithSum(allocator: mem.Allocator, n: usize) mem.Allocator.Error![]Triplet {
    var count: usize = 0;

    for (0..n) |a| {
        if (a < 3) continue;
        for (a + 1 .. n) |b| {
            const c = n - a - b;
            if (c <= b) break;
            const a_sq: u128 = @as(u128, a) * @as(u128, a);
            const b_sq: u128 = @as(u128, b) * @as(u128, b);
            const c_sq: u128 = @as(u128, c) * @as(u128, c);
            if (a_sq + b_sq == c_sq) {
                count += 1;
            }
        }
    }

    const result = try allocator.alloc(Triplet, count);
    errdefer allocator.free(result);

    var i: usize = 0;
    for (0..n) |a| {
        if (a < 3) continue;
        for (a + 1 .. n) |b| {
            const c = n - a - b;
            if (c <= b) break;
            const a_sq: u128 = @as(u128, a) * @as(u128, a);
            const b_sq: u128 = @as(u128, b) * @as(u128, b);
            const c_sq: u128 = @as(u128, c) * @as(u128, c);
            if (a_sq + b_sq == c_sq) {
                result[i] = Triplet.init(a, b, c);
                i += 1;
            }
        }
    }

    return result;
}
```

